.l-footer { background: $white; color: $black; padding: 0;
  &__panel { background: $black; border-radius: 24px; box-sizing: border-box; color: $white; height: 554px; margin-left: 36px; max-width: 1840px; padding: 52px 200px 24px; width: calc(100% - 80px); }
  &__grid { display: grid; gap: 42px; grid-template-columns: 2.4fr repeat(3, 1fr); }
  &__logo img { margin-bottom: 20px; width: 165px; }
  &__contact p, &__column p { font-size: 1.4rem; line-height: 1.4; margin: 0 0 10px; }
  &__contact p:first-of-type, &__column h2, &__awards h2 { font-size: 1.6rem; font-weight: 700; margin: 0 0 12px; }
  &__social img { height: 32px; margin-top: 8px; width: 32px; }
