}
@media (max-width: $breakpoint-md) { .l-footer__grid { grid-template-columns: 1fr 1fr; } .l-footer__awards { grid-column: auto; } }
@media (max-width: $breakpoint-sm) { .l-footer__panel { height: auto; margin-left: 0; max-width: none; padding: 30px 24px; width: 100%; } .l-footer__grid { grid-template-columns: minmax(0, 1fr); } .l-footer__grid > * { min-width: 0; } .l-footer__column p { overflow-wrap: anywhere; } .l-footer__awards { align-items: start; flex-direction: column; grid-column: auto; } .l-footer__awards > div { flex-wrap: wrap; max-width: 100%; } .l-footer__bottom { flex-direction: column; gap: 12px; } }
@use 'abstracts' as *;


.l-header {
  transition: $transition;
  position: sticky;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 100;

  &__container {
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  &--pinned {
    transform: translateY(0%);
    background: $base-background-colour;
  }

  &.header--not-top {
    background: $base-background-colour;

    .l-header__branding {
      img {
        max-width: 150px;
      }
    }
  }

  &--top {
    background: transparent;
  }

  &--unpinned {
    transform: translateY(-150%);
  }

  &__branding {
    display: flex;

    img {
      transition: $transition;
    }
  }

  &__menu {
    display: none;
    
    @include media($breakpoint-md, min) {
        display: flex;
    }
    
    ul {
        display: flex;
        gap: 3rem;

        li {
            position: relative;
            &.menu-item-has-children {
                a {
                    display: flex;
                    align-items: center;
                    gap: .4rem;
                }
            }

            ul {
                position: absolute;
                display: none;
                flex-direction: column;
                background-color: $white;
                gap: 0;
                left: -2rem;
                // box-shadow: $shadow;

                li {
                    a {
                        padding: .3rem 2rem;
                        text-wrap: nowrap;
                        display: block;
                        border-bottom: 1px solid rgba($gray-1, 0.9);

                        &:hover {
                            background-color: $gray-1;
                        }
                    }

                    &:last-child {
                        a {
                            border-bottom: none;
                        }
                    }
                }
            }
        }
    }
  }
}

.c-promotion-bar { background: $black; color: $white; font-size: 1.4rem; font-weight: 700; }
.c-promotion-bar__inner { align-items: center; display: flex; justify-content: center; min-height: 40px; }
.l-header {
