.l-footer { background: $white; color: $black; padding: 0;
  &__panel { background: $black; border-radius: 24px; box-sizing: border-box; color: $white; height: 554px; margin-left: 36px; max-width: 1840px; padding: 52px 200px 24px; width: calc(100% - 80px); }
  &__grid { display: grid; gap: 42px; grid-template-columns: 2.4fr repeat(3, 1fr); }
  &__logo img { margin-bottom: 20px; width: 165px; }
  &__contact p, &__column p { font-size: 1.4rem; line-height: 1.4; margin: 0 0 10px; }
  &__contact p:first-of-type, &__column h2, &__awards h2 { font-size: 1.6rem; font-weight: 700; margin: 0 0 12px; }
  &__social img { height: 32px; margin-top: 8px; width: 32px; }
  &__awards { align-items: end; display: flex; gap: 20px; grid-column: 3 / span 2; }
  &__awards h2 { max-width: 130px; }
  &__awards > div { align-items: center; display: flex; gap: 10px; }
  &__awards img { max-height: 38px; max-width: 44px; object-fit: contain; }
  &__legal { border-top: 1px solid #777; font-size: 1.3rem; font-weight: 700; line-height: 1.45; margin: 28px 0 0; padding-top: 18px; }
  &__bottom { display: flex; font-size: 1.2rem; justify-content: space-between; min-height: 60px; padding-top: 18px; }
}
@media (max-width: $breakpoint-md) { .l-footer__grid { grid-template-columns: 1fr 1fr; } .l-footer__awards { grid-column: auto; } }
@media (max-width: $breakpoint-sm) { .l-footer__panel { height: auto; margin-left: 0; max-width: none; padding: 30px 24px; width: 100%; } .l-footer__grid { grid-template-columns: minmax(0, 1fr); } .l-footer__grid > * { min-width: 0; } .l-footer__column p { overflow-wrap: anywhere; } .l-footer__awards { align-items: start; flex-direction: column; grid-column: auto; } .l-footer__awards > div { flex-wrap: wrap; max-width: 100%; } .l-footer__bottom { flex-direction: column; gap: 12px; } }
@use 'variables' as *;
@use 'mixins' as *;

// Lista wartoÅ›ci
$xl-min-values: (210, 150, 140, 130, 120, 110, 100, 90, 80, 70, 60, 50, 40, 30);
$scale-factors: (
    xl-max: calc(1 / 1.25),
    // 75% wartoÅ›ci poprzedniej
    md-max: calc(1 / 1.5625),
    // 75% wartoÅ›ci poprzedniej
    sm-max: calc(1 / 1.953125) // 75% wartoÅ›ci poprzedniej,,,,
);

// Tworzenie mapy spacing-values
$spacing-values: ();

@each $size in $xl-min-values {
    $breakpoints: (
        xl-min: #{$size}px,
    );

    @each $bp, $factor in $scale-factors {
        // Warunki dla wykluczania md-max i sm-max
        @if not(
            ($size == 30 or $size == 40) and
                ($bp == md-max or $bp == sm-max) or
                ($size == 50 or $size == 60) and
                ($bp == sm-max)
        )
        {
            $breakpoints: map-merge(
                $breakpoints,
                (
                    $bp: round($size * $factor) + px,
                )
            );
        }
    }

    $spacing-values: map-merge(
        $spacing-values,
        (
            $size: $breakpoints,
        )
    );
}

// Mixiny do generowania klas
@mixin generate-spacing($property) {
    @each $size, $breakpoints in $spacing-values {
        %#{$property}-#{$size} {
            @each $bp, $value in $breakpoints {
                @if $bp == xl-min {
                    @include media($breakpoint-xl, min) {
                        #{$property}: $value;
                    }
                } @else if $bp == xl-max {
                    @include media($breakpoint-xl, max) {
                        #{$property}: $value;
                    }
                } @else if $bp == md-max {
                    @include media($breakpoint-md, max) {
                        #{$property}: $value;
                    }
                } @else if $bp == sm-max {
                    @include media($breakpoint-sm, max) {
                        #{$property}: $value;
                    }
                }
            }
        }
    }
}

// Mixin dla osi x i y
