@use 'abstracts' as *;

input {
    &[type="text"] {
        @extend .custom-input;
    }
    
    &[type="email"] {
        @extend .custom-input;
    }
    
    &[type="tel"] {
        @extend .custom-input;
    }
    
    [type="radio"] {
        
    }
    
    &[type="checkbox"] {
        width: 20px;
        height: 20px;
        // background-color: $white;
        border: 1px solid $white;
        flex-shrink: 0;
        display: flex;
        justify-content: center;
        align-items: center;
        border-radius: 3px;

        &:before {
            content: '\f00c';
            font-family: 'Font Awesome 6 Free';
            font-weight: 900;
            display: none;
        }

        &:checked {
            &::before {
                display: block;
            }
        }
    }
    
    [type="button"] {
        
    }
    
    [type="submit"] {
        
    }
    
    [type="file"] {
        
    }
    
    [type="time"] {
        
    }
    
    [type="date"] {
        
    }
}

.custom-input {
    padding: 2.1rem 3.5rem;
    color: $white;
    font-family: $base-font-family;
    border: 3px solid $gray-1;
    width: 100%;
    border-radius: 50vh;
    text-align: center;

    &::placeholder {
        color: $gray-1;
        text-align: center;
    }

    &:focus {
        border-color: $accent;
    }
}
@use 'abstracts' as *;


.wpcf7 {
    .screen-reader-response {
        display: none;
    }

    form {
        color: $white;
        display: flex;
        flex-direction: column;
        gap: 6rem;

        textarea {
            // height: 200px;
        }

        .row {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 1.6rem;

            @include media($breakpoint-sm) {
                grid-template-columns: 1fr;
                textarea {
                    height: 150px;
                }
            }

            

            &.full {
                grid-template-columns: 1fr;

            }

            .col {
                height: 100%;

                p {
                    display: flex;
                    flex-direction: column;
                    justify-content: space-between;
                    height: 100%;

                    gap: 1.6rem;

                    br {
                        display: none;
                    }
                    span {
                        display: block;
                    }
                }
            }

            &.privacy {
                font-size: 1.6rem;
                line-height: 2.4rem;
                color: $gray-1;

                a {
                    color: $white;

                    &:hover {
                        color: $accent;
                    }
                }

                label {
                    display: flex;
                    gap: 1rem;

                    @include media($breakpoint-sm) {
                        font-size: 1.4rem;
                    }
                }
            }

            &.submit {
                display: flex;
                justify-content: center;
            }
        }

        .wpcf7-response-output {
            width: fit-content;
            margin: 0 auto;
            border-radius: 5px;
            font-size: 14px;
            line-height: 1;
            padding: 1rem 3rem;
        }

        &.invalid {
            .wpcf7-response-output {
                background-color: rgba($error-colour, .9);
                border: 1px solid $error-colour;
                
            }
        }
        &.sent {
            .wpcf7-response-output {
                background-color: rgba($success-colour, .9);
                border: 1px solid $success-colour;
                
            }
        }
        &.unaccepted {
            .wpcf7-response-output {
                background-color: rgba($warning-colour, .9);
                border: 1px solid $warning-colour;
                
            }

            input[type="checkbox"] {
                border: 1px solid rgba($error-colour, 1);
            }
        }
    }

    .wpcf7-form-control-wrap {
        position: relative;
        .wpcf7-not-valid-tip {
            position: absolute;
            left: -.2rem;
            bottom: -1.6rem;
            background-color: rgba($error-colour, .9);
            border: 1px solid $error-colour;
            border-radius: 5px;
            font-size: 12px;
            line-height: 1;
            padding: .4rem;

        }
    }

    
}

